.bc-multi-resize{width:10px;height:10px;border:2px solid #6175ff;border-radius:2px;background:#fff;z-index:3}
.bc-multi-port{width:9px;height:9px;border:2px solid #42a5ff;border-radius:50%;background:#101722;z-index:4;opacity:.15;transition:opacity .12s,transform .12s}
.bc-multi-selection-frame:hover .bc-multi-port{opacity:1}
.bc-multi-port:hover{background:#52b5ff;transform:translate(-50%,-50%) scale(calc(var(--world-inverse-scale,1)*1.35))}
.bc-multi-resize.bc-nw,.bc-multi-port.bc-nw{left:0;top:0}.bc-multi-resize.bc-n,.bc-multi-port.bc-n{left:50%;top:0}.bc-multi-resize.bc-ne,.bc-multi-port.bc-ne{left:100%;top:0}.bc-multi-resize.bc-e,.bc-multi-port.bc-e{left:100%;top:50%}.bc-multi-resize.bc-se,.bc-multi-port.bc-se{left:100%;top:100%}.bc-multi-resize.bc-s,.bc-multi-port.bc-s{left:50%;top:100%}.bc-multi-resize.bc-sw,.bc-multi-port.bc-sw{left:0;top:100%}.bc-multi-resize.bc-w,.bc-multi-port.bc-w{left:0;top:50%}
.bc-multi-port.bc-nw{margin:-11px 0 0 -11px}.bc-multi-port.bc-n{margin-top:-13px}.bc-multi-port.bc-ne{margin:-11px 0 0 11px}.bc-multi-port.bc-e{margin-left:13px}.bc-multi-port.bc-se{margin:11px 0 0 11px}.bc-multi-port.bc-s{margin-top:13px}.bc-multi-port.bc-sw{margin:11px 0 0 -11px}.bc-multi-port.bc-w{margin-left:-13px}
.bc-group-connect-preview{position:absolute;inset:0;width:100%;height:100%;overflow:visible;pointer-events:none;z-index:160}.bc-group-connect-preview path{fill:none;stroke:#58a0ff;stroke-width:3;stroke-dasharray:8 6;vector-effect:non-scaling-stroke}
/* observed objects tab */
#bcObservedTab{min-width:0}.observed-gallery{display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:7px!important;padding:7px!important;align-content:start!important}.bc-observed-tile{min-width:0;height:82px;border:1px solid var(--line);border-radius:9px;background:var(--surface-2);color:var(--text);display:grid;grid-template-rows:1fr auto;place-items:center;padding:5px;overflow:hidden}.bc-observed-tile.selected{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent)}.bc-observed-tile img{width:100%;height:50px;object-fit:cover;border-radius:6px}.bc-observed-tile>span{width:42px;height:42px;display:grid;place-items:center}.bc-observed-tile>span svg{width:22px;height:22px}.bc-observed-tile b{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:9px;font-weight:650}
/* screenshot studio */
.bc-shot-studio{position:absolute;inset:0;z-index:900;background:rgba(5,9,16,.82);display:grid;place-items:center;padding:18px;overflow:auto}.bc-shot-studio canvas{max-width:calc(100% - 20px);max-height:calc(100% - 20px);width:auto;height:auto;box-shadow:0 22px 70px rgba(0,0,0,.42);border-radius:8px;cursor:crosshair}.bc-shot-mask{pointer-events:none}.bc-shot-tools{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;margin:9px 0}.bc-shot-tools button{height:34px;border:1px solid var(--line);background:var(--surface-2);color:var(--text);border-radius:8px;font-size:11px}.bc-shot-tools button.active{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 14%,var(--surface-2))}
/* compact observed-context strip in chat */
.gpt-context-tray{position:relative!important;display:flex!important;align-items:center!important;gap:5px!important;min-width:0!important;padding:4px 0!important;overflow:visible!important}.gpt-context-tray[hidden]{display:none!important}.gpt-context-strip{display:flex;gap:5px;min-width:0;overflow:hidden;mask-image:linear-gradient(90deg,#000 0,#000 calc(100% - 24px),transparent 100%);-webkit-mask-image:linear-gradient(90deg,#000 0,#000 calc(100% - 24px),transparent 100%);flex:1}.gpt-context-chip.compact{flex:0 0 auto;width:134px;max-width:134px;height:34px;min-height:34px;padding:3px 5px!important;display:grid!important;grid-template-columns:25px minmax(0,1fr) 18px!important;align-items:center!important;gap:5px!important;overflow:hidden!important;border-radius:8px!important}.gpt-context-chip.compact>img{width:25px;height:25px;object-fit:cover;border-radius:5px}.gpt-context-chip.compact .gpt-context-eye{width:25px;height:25px;display:grid;place-items:center}.gpt-context-chip.compact strong{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:9px!important}.gpt-context-chip.compact button{width:18px!important;height:18px!important;padding:0!important}.gpt-context-expand{width:30px;height:30px;flex:0 0 30px;border:1px solid var(--line);border-radius:8px;background:var(--surface-2);color:var(--muted);display:grid;place-items:center}.gpt-context-expand svg{width:12px;height:12px;transform:rotate(-90deg);transition:transform .16s}.gpt-context-tray.expanded .gpt-context-expand svg{transform:rotate(90deg)}.gpt-context-expanded{display:none;position:absolute;left:0;right:0;bottom:43px;z-index:30;max-height:260px;overflow:auto;padding:8px;background:var(--gpt-panel-bg,var(--surface));border:1px solid var(--line);border-radius:12px;box-shadow:0 -18px 42px rgba(0,0,0,.28);grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.gpt-context-tray.expanded .gpt-context-expanded{display:grid}.gpt-context-card{min-width:0;height:58px;border:1px solid var(--line);border-radius:9px;background:var(--surface-2);color:var(--text);display:grid;grid-template-columns:42px minmax(0,1fr);align-items:center;gap:7px;text-align:left;padding:6px}.gpt-context-card img,.gpt-context-card-icon{width:42px;height:42px;border-radius:7px;object-fit:cover;background:var(--surface);display:grid;place-items:center;font-size:8px;font-weight:800}.gpt-context-card span:last-child{min-width:0}.gpt-context-card strong,.gpt-context-card small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.gpt-context-card strong{font-size:10px}.gpt-context-card small{font-size:8px;color:var(--muted);margin-top:3px}
/* agent elapsed / estimated progress */
.ai-task-progress{position:fixed;z-index:9950;width:164px;height:24px;pointer-events:none;border-radius:8px;background:color-mix(in srgb,var(--surface) 78%,transparent);border:1px solid color-mix(in srgb,var(--task-color,#8b5cf6) 34%,var(--line));box-shadow:0 8px 28px rgba(0,0,0,.18);overflow:hidden;backdrop-filter:blur(8px);transition:opacity .45s,transform .45s}.ai-task-progress>span{position:absolute;inset:0 auto 0 0;width:var(--task-pct,6%);background:linear-gradient(90deg,color-mix(in srgb,var(--task-color,#8b5cf6) 18%,transparent),color-mix(in srgb,var(--task-color,#8b5cf6) 48%,transparent));transition:width .28s ease}.ai-task-progress>small{position:relative;z-index:1;height:100%;display:flex;align-items:center;padding:0 8px;color:var(--text);font-size:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.ai-task-progress.done{opacity:0;transform:translateY(-4px)}
